const rows = $input.all().map(i => i.json);
const today = new Date().toISOString().slice(0, 10);
const todays = rows.filter(r => (r['التاريخ'] || '').startsWith(today));
const byBranch = {};
let compensated = 0;
for (const r of todays) {
  const b = r['الفرع'] || 'غير محدد';
  byBranch[b] = (byBranch[b] || 0) + 1;
  if (r['حالة التعويض'] === 'تم التعويض') compensated++;
}
let text = `📊 تقرير الفواتير الملغية — ${today}\n`;
text += `الإجمالي: ${todays.length} | تم تعويضها: ${compensated} | في انتظار التعويض: ${todays.length - compensated}\n`;
for (const [b, c] of Object.entries(byBranch)) text += `• ${b}: ${c}\n`;
if (todays.length === 0) text += 'لا توجد فواتير ملغية اليوم ✅';
return [{ json: { text } }];
